mapper.select:
select
/*名下人员数量*/
(select count(1) from survey_investigator t
  left join bus_user_role b on t.user_id = b.user_id
where t.delete_flag = 0 and t.org_id = #{surveyOrgId,jdbcType=BIGINT} and b.role_id = 50
) as basSurveyUsers,

/*机构待分派*/
(SELECT count(1) FROM survey_assign_org a
    LEFT JOIN survey_risk_case_info s1 ON a.survey_info_id = s1.id
    LEFT JOIN survey_risk_case s2 ON a.survey_id = s2.id
    WHERE 1 = 1 AND a.delete_flag = 0 AND s1.delete_flag = 0 AND s2.delete_flag = 0
    AND a.org_survey_state IN (0, 1, 5) AND a.survey_investigator_case_id IS NULL

        and a.survey_org_id = #{surveyOrgId,jdbcType=BIGINT}


        and s1.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}


        and s1.entrust_org_id in (${entrustOrgIds})

) as basOrgNotAss,
/*机构调查中*/
(select count(1) from survey_risk_case_info s left join survey_assign_org ao on ao.survey_info_id = s.id
  where s.delete_flag = 0 and ao.delete_flag = 0 and ao.org_survey_state in (1)

        and ao.survey_org_id = #{surveyOrgId,jdbcType=BIGINT}


        and s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}


        and s.entrust_org_id  in (${entrustOrgIds})

) as basOrgSurveying,

/*初审中*/
(select count(1) from survey_risk_case_info s left join survey_assign_org ao on ao.survey_info_id = s.id
where s.delete_flag = 0  and ao.delete_flag = 0 and ao.org_survey_state in (2,5)

        and ao.survey_org_id = #{surveyOrgId,jdbcType=BIGINT}


        and s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}


        and s.entrust_org_id  in (${entrustOrgIds})

) as basOrgReviewing,
/*平台待终审*/
(select count(1) from survey_risk_case_info s left join survey_assign_org ao on ao.survey_info_id = s.id
    where s.delete_flag = 0 and s.survey_state in (22,30) and ao.delete_flag = 0

        and ao.survey_org_id = #{surveyOrgId,jdbcType=BIGINT}


        and s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}


        and s.entrust_org_id  in (${entrustOrgIds})

)as basLefanApv,

/*保司待审核*/
(select count(1) from survey_risk_case_info s left join survey_assign_org ao on ao.survey_info_id = s.id
    where s.delete_flag = 0 and s.survey_state = 24 and ao.delete_flag = 0

        and ao.survey_org_id = #{surveyOrgId,jdbcType=BIGINT}


        and s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}


        and s.entrust_org_id  in (${entrustOrgIds})

) as basEntrustApv,
/*财务待结案basNotClose*/
(select count(1) from survey_risk_case_info s left join survey_assign_org ao on ao.survey_info_id = s.id
    where s.delete_flag = 0 and s.entrust_report_end_date is not null and s.survey_phase != 3 and ao.delete_flag = 0

        and ao.survey_org_id = #{surveyOrgId,jdbcType=BIGINT}


        and s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}


        and s.entrust_org_id  in (${entrustOrgIds})

)as basNotClose

from dual

select min(report_date) as minReportDate from survey_investigator_org_report
where survey_org_id = #{surveyOrgId,jdbcType=BIGINT} and consignor_org_id = #{entrustOrgId,jdbcType=BIGINT}
and check_type = #{checkType,jdbcType=BIGINT}

select max(report_date) as maxReportDate from survey_investigator_org_report
where survey_org_id = #{surveyOrgId,jdbcType=BIGINT} and consignor_org_id = #{entrustOrgId,jdbcType=BIGINT}
and check_type = #{checkType,jdbcType=BIGINT}
